class Cell:
    def __init__(self):
        self._inputs = []
        self._dependents = []

    def _add_dependent(self, dependent):
        self._dependents.append(dependent)


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._propagate()

    def _propagate(self):
        # Collect every cell (transitively) that depends on this input.
        affected = set()
        stack = [self]
        while stack:
            cell = stack.pop()
            for dependent in cell._dependents:
                if dependent not in affected:
                    affected.add(dependent)
                    stack.append(dependent)

        # Topologically sort the affected cells so that each cell's
        # dependencies are recomputed before the cell itself. This way
        # every cell is recomputed exactly once and ends up in a stable
        # state, and callbacks only fire for values that actually changed.
        order = []
        visited = set()

        def visit(cell):
            if cell in visited:
                return
            visited.add(cell)
            for dependency in cell._inputs:
                if dependency in affected:
                    visit(dependency)
            order.append(cell)

        for cell in affected:
            visit(cell)

        for cell in order:
            cell._recompute()


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        self._callbacks = []
        self._value = None
        for cell in self._inputs:
            cell._add_dependent(self)
        self._recompute()

    @property
    def value(self):
        return self._value

    def _recompute(self):
        new_value = self._compute_function([cell.value for cell in self._inputs])
        if new_value != self._value:
            self._value = new_value
            for callback in self._callbacks:
                callback(new_value)

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

